"""langsmith_lab.py  --  Lab 10 · Part D · run our 14-question exam as LangSmith EXPERIMENTS.   >>> YOU DO NOT EDIT THIS FILE <<<

Run:   python langsmith_lab.py                 (v1 and v3, all 14 questions, about 3 minutes)
       python langsmith_lab.py --quick         (first 5 questions only, if time is short)
       python langsmith_lab.py --prompts v1 v2 v3

What happens (this is how real teams run evals, with the same 5 checks from tab 4):
  DATASET     the 14 questions are uploaded once to your LangSmith account  (askit-ops-14)
  EXPERIMENT  for each prompt version the agent answers all 14 questions; every model call and tool call is a TRACE
  EVALUATORS  our plain-code checks (right tool, no runaway loop, grounded, safe write, budget) score every answer 1 or 0
  COMPARE     you open both experiments in LangSmith and see v1 vs v3 side by side
"""
import argparse
import os
import sys
import threading
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

import model_factory as mf   # noqa: E402,I001  (loads the .env files first: AWS keys, LANGSMITH_API_KEY)
import ops_agent as oa       # noqa: E402
import ops_trace as ot       # noqa: E402
import evals as ev           # noqa: E402

DATASET = "askit-ops-14"
TRACES = {}                  # trace_id -> full trace (the evaluators read the spans from here; the LangSmith output stays short)
_lock = threading.Lock()


def need_key():
    if not os.getenv("LANGSMITH_API_KEY"):
        print("No LangSmith key found. First run:  python langsmith_setup.py   (or double-click langsmith_1_setup.bat)")
        sys.exit(1)
    os.environ["LANGSMITH_TRACING"] = "true"                # only for this script: every model call below is traced
    os.environ.setdefault("LANGSMITH_PROJECT", "askit-day10")


# ------------------------------------------------------------------------------------------------ dataset
def ensure_dataset(client):
    """Upload the 14 questions once. Re-running this script reuses the dataset."""
    if client.has_dataset(dataset_name=DATASET):
        return
    ds = client.create_dataset(dataset_name=DATASET, description="AskIT helpdesk exam: 14 questions, 5 risk checks (Day 10 lab)")
    client.create_examples(
        dataset_id=ds.id,
        inputs=[{"case_id": c[0], "question": c[1]} for c in ev.CASES],
        outputs=[{"expected_tool": c[2], "expected_doc": c[3], "tag": c[4]} for c in ev.CASES],
        metadata=[{"kind": c[4]} for c in ev.CASES])
    print(f"Uploaded {len(ev.CASES)} exam questions to your LangSmith dataset '{DATASET}'.")


# ------------------------------------------------------------------------------------------------ the thing LangSmith runs
def patch_tool_spans():
    """Make every tool call show up as its own span (the model calls are traced by LangChain itself)."""
    from langsmith import traceable
    original = oa.run_tool

    def traced_run_tool(name, args, flags):
        return traceable(run_type="tool", name=name)(original)(name, args, flags)
    oa.run_tool = traced_run_tool


def make_target(model, provider, prompt_name):
    def target(inputs: dict) -> dict:
        tr = ot.Tracer(f"ls {inputs['case_id']}", model=mf.model_id(provider), provider=provider, price_key=mf.price_key(provider),
                       tags={"prompt": prompt_name, "case": inputs["case_id"]})
        try:
            oa.run_agent(inputs["question"], model, provider, tr, system_prompt=oa.PROMPTS[prompt_name])
        except Exception as e:                                          # noqa: BLE001
            tr.trace["status"] = "error"
            tr.trace["answer"] = f"(error) {type(e).__name__}: {str(e)[:160]}"
        t = tr.trace
        with _lock:
            TRACES[t["trace_id"]] = t
            ot.save(t)                                                  # also visible in the lab app, tab 1
        return {"answer": t["answer"], "tools_used": ev.tools_used(t), "llm_calls": t.get("llm_calls", 0), "tokens_in": t.get("tokens_in", 0),
                "cost_usd": t.get("cost_usd", 0), "seconds": round(t.get("ms", 0) / 1000, 1), "status": t.get("status"), "trace_id": t["trace_id"]}
    return target


def exam_evaluator(run, example):
    """Our 5 checks from evals.py, returned to LangSmith as one score per risk (1 = PASS, 0 = FAIL)."""
    trace = TRACES.get((run.outputs or {}).get("trace_id", ""))
    if trace is None:
        return {"results": [{"key": "eval_all_pass", "score": 0, "comment": "the agent run failed before it produced a trace"}]}
    case = (example.inputs["case_id"], example.inputs["question"], example.outputs["expected_tool"], example.outputs["expected_doc"], example.outputs["tag"])
    res = ev.check(case, trace)
    results = [{"key": f"eval_{k}", "score": 1 if v else 0} for k, v in res.items() if v is not None]
    results.append({"key": "eval_all_pass", "score": 1 if all(v for v in res.values() if v is not None) else 0})
    return {"results": results}


# ------------------------------------------------------------------------------------------------ run
def short(name):
    return name.split(" ")[0]                                          # "v1 · plain" -> "v1"


def pick_prompts(wanted):
    out = []
    for w in wanted:
        hit = [n for n in oa.PROMPTS if n.lower().startswith(w.lower())]
        if not hit:
            print(f"Unknown prompt '{w}'. Choose from: " + ", ".join(short(n) for n in oa.PROMPTS))
            sys.exit(1)
        out.append(hit[0])
    return out


def table(rows):
    cats = ev.CATS
    print("\n" + "=" * 78 + "\nRESULT  (PASS count / questions where the check applies)\n" + "=" * 78)
    print(f"{'prompt':<8}" + "".join(f"{ev.CAT_TEXT[c][:17]:<19}" for c in cats) + "all-pass")
    for name, traces in rows:
        line = f"{short(name):<8}"
        for c in cats:
            vals = [ev.check(case, traces[case[0]])[c] for case in ev.CASES if case[0] in traces]
            vals = [v for v in vals if v is not None]
            line += f"{sum(vals)}/{len(vals):<17}"
        allp = sum(1 for case in ev.CASES if case[0] in traces and all(v for v in ev.check(case, traces[case[0]]).values() if v is not None))
        print(line + f"{allp}/{len([c for c in ev.CASES if c[0] in traces])}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--prompts", nargs="+", default=["v1", "v3"], help="prompt versions to compare (default: v1 v3)")
    ap.add_argument("--quick", action="store_true", help="only the first 5 questions")
    ap.add_argument("--provider", default="", help="bedrock, azure, openai or offline (default: Auto, same as the app)")
    ap.add_argument("--workers", type=int, default=4)
    a = ap.parse_args()

    need_key()
    from langsmith import Client
    client = Client()
    try:
        ensure_dataset(client)
    except Exception as e:                                              # noqa: BLE001
        print(f"Could not talk to LangSmith: {type(e).__name__}: {str(e)[:200]}\nRun  python langsmith_setup.py --check  to test your key.")
        return 1
    patch_tool_spans()

    provider = a.provider or mf.auto_provider()
    model = mf.get_model(provider)
    print(f"Model: {mf.model_label(provider)}")
    if provider == "offline":
        print("NOTE: the Offline stand-in is not a real model; the experiment works, but the numbers are only for practice.")
    chosen = pick_prompts(a.prompts)

    examples = list(client.list_examples(dataset_name=DATASET))
    examples.sort(key=lambda e: e.inputs["case_id"])
    if a.quick:
        examples = examples[:5]
    rows = []
    for pname in chosen:
        print(f"\n>>> Experiment for prompt {short(pname)}: {len(examples)} questions ...")
        before = set(TRACES)
        res = client.evaluate(make_target(model, provider, pname), data=examples, evaluators=[exam_evaluator],
                              experiment_prefix=f"askit-{short(pname)}-{provider}", max_concurrency=a.workers,
                              metadata={"prompt": pname, "model": mf.model_id(provider), "provider": provider})
        by_case = {t["tags"]["case"]: t for tid, t in TRACES.items() if tid not in before}
        rows.append((pname, by_case))
        url = ""
        try:
            url = client.read_project(project_name=res.experiment_name).url or ""
        except Exception:                                               # noqa: BLE001
            pass
        print(f"    done: experiment '{res.experiment_name}'" + (f"\n    open: {url}" if url else ""))
    table(rows)
    print("""
NOW IN THE BROWSER  (https://smith.langchain.com)
  1. Left menu: Datasets & Experiments  ->  askit-ops-14  ->  Experiments tab
  2. Tick the v1 and the v3 experiment  ->  Compare.  Columns = the 5 risks (eval_tool, eval_runaway, eval_grounded, eval_safe, eval_budget).
  3. Click a red (0) cell, then 'Trace': read the waterfall of that run. Is it the same kind of failure you saw in tab 4?
  4. Which question got WORSE from v1 to v3, if any? That is a regression: the reason we run the exam before every release.""")
    return 0


if __name__ == "__main__":
    sys.exit(main())
